using System;
using System.IO;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.Rendering.Universal;
using Nexoterra.World;
namespace Nexoterra.Editor{
[InitializeOnLoad] public static class NaturalMotionRuntimeReview{
 static int step=-1;static float at;static NexoterraThirdPerson p;static NativePlayerAnimation driver;static string[] states={"Aim","Walk","Run","Idle"};static bool calibrated;static GripData gripData=new GripData();
 [Serializable] public class GripData{public Vector3 male,female,maleSupport,femaleSupport;public Quaternion maleRotation,femaleRotation,maleSupportRotation,femaleSupportRotation;}
 static NaturalMotionRuntimeReview(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("MotionReview",false)){EditorSceneManager.playModeStartScene=AssetDatabase.LoadAssetAtPath<SceneAsset>(SessionState.GetString("MotionReview.Start",""));SessionState.SetBool("MotionReview",false);EditorApplication.delayCall+=ApplyGrip;}};}
 static void Tick(){
 if(!EditorApplication.isPlayingOrWillChangePlaymode&&!EditorApplication.isCompiling&&File.Exists("Library/MotionReview.request")){File.Delete("Library/MotionReview.request");SessionState.SetString("MotionReview.Start",AssetDatabase.GetAssetPath(EditorSceneManager.playModeStartScene));SessionState.SetBool("MotionReview",true);EditorSceneManager.playModeStartScene=null;EditorSceneManager.OpenScene(NexoterraBiomeBuilder.ScenePath);EditorApplication.isPlaying=true;return;}
 if(!SessionState.GetBool("MotionReview",false)||!EditorApplication.isPlaying||!GameSession.Current||!GameSession.Current.Ready||Time.time<2)return;
 try{
 if(step<0){p=GameSession.Current.GetComponent<NexoterraThirdPerson>();driver=p.GetComponent<NativePlayerAnimation>();p.Teleport(new Vector3(0,3000,0));p.enabled=false;driver.enabled=false;p.GetComponent<CharacterController>().enabled=false;p.GetComponent<GameSession>().menu=false;foreach(var c in p.GetComponentsInChildren<Camera>())c.GetUniversalAdditionalCameraData().renderShadows=false;RenderSettings.fog=false;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.4f,.4f,.4f);var l=new GameObject("Review key").AddComponent<Light>();l.type=LightType.Directional;l.intensity=2;l.transform.rotation=Quaternion.Euler(25,150,0);step=0;SetPose();return;}
 if(Time.time-at<.5f)return;
 if(step%4==0&&!calibrated){var a=step>=4?driver.female:driver.male;var hand=a.GetBoneTransform(HumanBodyBones.RightHand);var left=a.GetBoneTransform(HumanBodyBones.LeftHand);driver.weapon.SetPositionAndRotation(hand.position+new Vector3(0,-.09f,.1f),Quaternion.identity);var ik=a.GetComponent<HumanoidWeaponIK>();ik.supportOffset=hand.InverseTransformPoint(driver.weapon.TransformPoint(new Vector3(-.035f,.17f,.04f)));ik.supportRotation=Quaternion.Inverse(hand.rotation)*left.rotation;ik.enabled=true;if(step>=4){gripData.female=driver.weapon.localPosition;gripData.femaleRotation=driver.weapon.localRotation;gripData.femaleSupport=ik.supportOffset;gripData.femaleSupportRotation=ik.supportRotation;}else{gripData.male=driver.weapon.localPosition;gripData.maleRotation=driver.weapon.localRotation;gripData.maleSupport=ik.supportOffset;gripData.maleSupportRotation=ik.supportRotation;}calibrated=true;at=Time.time;return;}Capture();step++;if(step>=8){File.WriteAllText("Library/Locomotion/Grip.json",JsonUtility.ToJson(gripData,true));File.WriteAllText("Library/MotionReview.result.txt","PASS runtime snapshots; originals rolls unchanged.");EditorApplication.isPlaying=false;return;}SetPose();
 }catch(Exception e){File.WriteAllText("Library/MotionReview.result.txt",e.ToString());EditorApplication.isPlaying=false;}
 }
 static void SetPose(){calibrated=false;bool female=step>=4;p.male.SetActive(!female);p.female.SetActive(female);typeof(NativePlayerAnimation).GetMethod("Update",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(driver,null);var a=female?driver.female:driver.male;string state=states[step%4];driver.GetType().GetProperty("AimWeight").SetValue(driver,state=="Aim"?1f:0f);if(step%4==0)a.GetComponent<HumanoidWeaponIK>().enabled=false;a.speed=1;a.Play(state=="Aim"?"Idle":state,0,.05f);a.SetLayerWeight(1,state=="Aim"?1:0);p.visuals.rotation=Quaternion.identity;var cam=p.view;cam.transform.position=p.transform.position+new Vector3(2.5f,1.7f,4);cam.transform.LookAt(p.transform.position+Vector3.up*1);cam.fieldOfView=34;cam.farClipPlane=20;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.055f,.07f,.09f);at=Time.time;}
 static void ApplyGrip(){if(!File.Exists("Library/Locomotion/Grip.json"))return;var d=JsonUtility.FromJson<GripData>(File.ReadAllText("Library/Locomotion/Grip.json"));var p=UnityEngine.Object.FindAnyObjectByType<NativePlayerAnimation>();p.maleGrip=d.male;p.femaleGrip=d.female;p.maleGripRotation=d.maleRotation;p.femaleGripRotation=d.femaleRotation;p.gripHeightCorrection=0;var m=p.male.GetComponent<HumanoidWeaponIK>();m.supportOffset=d.maleSupport;m.supportRotation=d.maleSupportRotation;var f=p.female.GetComponent<HumanoidWeaponIK>();f.supportOffset=d.femaleSupport;f.supportRotation=d.femaleSupportRotation;EditorSceneManager.MarkSceneDirty(p.gameObject.scene);EditorSceneManager.SaveScene(p.gameObject.scene);AssetDatabase.SaveAssets();}
 static void Capture(){var rt=new RenderTexture(720,720,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(p.view,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var tex=new Texture2D(720,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,720,720),0,0);tex.Apply();File.WriteAllBytes("Documentation/Nexoterra/Locomotion/Runtime_"+(step>=4?"Female_":"Male_")+states[step%4]+".png",tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.Destroy(rt);}}
}}
